-- All individual content sharing follows the canonical file sharing ceiling.
-- Folder methods keep their actual FOLDER kind; authorities belong to the same Document service.
INSERT INTO iam_policy_authority SELECT p.id,'document-service',a.id,3 FROM iam_operation_policy p JOIN iam_operation o ON o.id=p.operation_id AND o.service_id=p.service_id JOIN iam_authority a ON a.service_id=p.service_id AND a.authority_key='file.share' WHERE o.service_id='document-service' AND o.operation_key='folder.share.view';
INSERT INTO iam_policy_authority SELECT p.id,'document-service',a.id,4 FROM iam_operation_policy p JOIN iam_operation o ON o.id=p.operation_id AND o.service_id=p.service_id JOIN iam_authority a ON a.service_id=p.service_id AND a.authority_key='file.share.view' WHERE o.service_id='document-service' AND o.operation_key='folder.share.view';
INSERT INTO iam_policy_authority SELECT p.id,'document-service',a.id,3 FROM iam_operation_policy p JOIN iam_operation o ON o.id=p.operation_id AND o.service_id=p.service_id JOIN iam_authority a ON a.service_id=p.service_id AND a.authority_key='file.share' WHERE o.service_id='document-service' AND o.operation_key='folder.share.edit';
INSERT INTO iam_policy_authority SELECT p.id,'document-service',a.id,4 FROM iam_operation_policy p JOIN iam_operation o ON o.id=p.operation_id AND o.service_id=p.service_id JOIN iam_authority a ON a.service_id=p.service_id AND a.authority_key='file.share.edit' WHERE o.service_id='document-service' AND o.operation_key='folder.share.edit';
UPDATE iam_operation_policy p JOIN iam_operation o ON o.id=p.operation_id AND o.service_id=p.service_id SET p.version=p.version+1,p.updated_at=UTC_TIMESTAMP(6) WHERE o.service_id='document-service' AND o.operation_key IN ('folder.share.view','folder.share.edit');
UPDATE iam_policy_revision SET revision=revision+1 WHERE id='GLOBAL';
